    public Object parseTicker(Object ticker, Map<String, Object> market)
    {
        //
        //     {
        //         "btc":{
        //             "bid":"51970",
        //             "ask":"53000",
        //             "last":"52806.47"
        //         }
        //     }
        //
        String symbol = this.safeSymbol(null, market, (String) null, (String) null);
        String last = this.safeString(ticker, "last");
        return this.safeTicker(new HashMap<String, Object>() {{
            put( "symbol", symbol );
            put( "timestamp", null );
            put( "datetime", null );
            put( "high", null );
            put( "low", null );
            put( "bid", Coinspot.this.safeString(ticker, "bid") );
            put( "bidVolume", null );
            put( "ask", Coinspot.this.safeString(ticker, "ask") );
            put( "askVolume", null );
            put( "vwap", null );
            put( "open", null );
            put( "close", last );
            put( "last", last );
            put( "previousClose", null );
            put( "change", null );
            put( "percentage", null );
            put( "average", null );
            put( "baseVolume", null );
            put( "quoteVolume", null );
            put( "info", ticker );
        }}, market);
    }

    /**
     * @method
     * @name coinspot#fetchTicker
     * @description fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market
     * @see https://www.coinspot.com.au/api#latestprices
     * @param {string} symbol unified symbol of the market to fetch the ticker for
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/?id=ticker-structure}
     */
    public CompletableFuture<Ticker> fetchTicker(String symbol, Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            if (java.util.Objects.equals(this.markets, null))
            {
                (this.loadMarkets(false, new HashMap<String, Object>() {{}})).join();
            }
            Map<String, Object> market = (Map<String, Object>) this.market(symbol);
            Map<String, Object> response = (this.publicGetLatest(parameters)).join();
            String id = this.safeString(market, "id", "");
            id = id.toLowerCase();
            Map<String, Object> prices = (Map<String, Object>) this.safeDict(response, "prices", new HashMap<String, Object>() {{}});
            //
            //     {
            //         "status":"ok",
            //         "prices":{
            //             "btc":{
            //                 "bid":"52732.47000022",
            //                 "ask":"53268.0699976",
            //                 "last":"53284.03"
            //             }
            //         }
            //     }
            //
            Map<String, Object> ticker = (Map<String, Object>) this.safeDict(prices, id, new HashMap<String, Object>() {{}});
            return this.parseTicker(ticker, market);
        }).thenApply(Ticker::new);

    }

    /**
     * @method
     * @name coinspot#fetchTickers
     * @description fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market
     * @see https://www.coinspot.com.au/api#latestprices
     * @param {string[]|undefined} symbols unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/?id=ticker-structure}
     */
    public CompletableFuture<Tickers> fetchTickers(List<String> symbols, Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            if (java.util.Objects.equals(this.markets, null))
            {
                (this.loadMarkets(false, new HashMap<String, Object>() {{}})).join();
            }
            Map<String, Object> response = (this.publicGetLatest(parameters)).join();
            //
            //    {
            //        "status": "ok",
            //        "prices":   {
            //            "btc":   {
            //                "bid": "25050",
            //                "ask": "25370",
            //                "last": "25234"
            //            },
            //            "ltc":   {
            //                "bid": "79.39192993",
            //                "ask": "87.98",
            //                "last": "87.95"
            //            }
            //        }
            //    }
            //
            Map<String, Object> result = new HashMap<String, Object>() {{}};
            Map<String, Object> prices = (Map<String, Object>) this.safeDict(response, "prices", new HashMap<String, Object>() {{}});
            List<String> ids = new ArrayList<String>(prices.keySet());
            for (var i = 0; i < ((List<?>)ids).size(); i++)
            {
                String id = (ids == null || i < 0 || i >= ids.size() ? null : ids.get(i));
                Map<String, Object> market = (Map<String, Object>) this.safeMarket(id, (Map<String, Object>) null, (String) null, (String) null);
                if (java.util.Objects.equals(((Map<String, Object>)market).get("spot"), true))
                {
                    String symbol = (String) ((Map<String, Object>)market).get("symbol");
                    Object ticker = (prices == null || id == null ? null : prices.get(id));
                    result.put((String)symbol, this.parseTicker(ticker, market));
                }
            }
            return this.filterByArrayTickers(result, "symbol", symbols, true);
        }).thenApply(Tickers::new);

    }

